-- Hoy.com.py (1560): frozen RSS -> html crawler (data only). Generated by Build-Sql.py. Reverse: reverse.sql.
\set ON_ERROR_STOP on
SET lock_timeout = '5s';
BEGIN;
SELECT 'before|' || id || '|' || feed_type || '|' || enabled || '|' || feed_url FROM feeds WHERE publisher_id = 1560 ORDER BY id;
DO $do$
DECLARE k int;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM publishers WHERE id = 1560 AND name = 'Hoy.com.py' AND feed_status = 'active') THEN
    RAISE EXCEPTION 'publisher 1560 is not the active Hoy.com.py - nothing changed'; END IF;
  IF (SELECT count(*) FROM feeds WHERE publisher_id = 1560) <> 1 THEN
    RAISE EXCEPTION 'Hoy.com.py has other sources - nothing changed'; END IF;
  IF EXISTS (SELECT 1 FROM feeds WHERE feed_url = 'https://www.hoy.com.py/') THEN
    RAISE EXCEPTION 'a source with the new URL already exists - nothing changed'; END IF;
  UPDATE feeds SET enabled = false WHERE publisher_id = 1560 AND feed_url = 'https://www.hoy.com.py/rss' AND feed_type = 'rss' AND enabled;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION 'old RSS feed: % rows, expected 1 - nothing changed', k; END IF;
  INSERT INTO feeds (publisher_id, feed_url, feed_type, crawl_frequency_minutes, enabled, respect_robots_txt,
                     allowed_domains, category_urls, article_url_patterns, parser_config)
  VALUES (1560, 'https://www.hoy.com.py/', 'html', 30, true, true, ARRAY['hoy.com.py']::text[], ARRAY['https://www.hoy.com.py/nacionales', 'https://www.hoy.com.py/politica', 'https://www.hoy.com.py/mundo']::text[], ARRAY['*/2026/*', '*/2027/*']::text[], '{"title_prefix": "Diario HOY | "}'::jsonb);
END $do$;
SELECT 'after|' || id || '|' || feed_type || '|' || enabled || '|' || coalesce(crawl_frequency_minutes::text, '-') || '|' || feed_url
  || '|' || coalesce(array_length(category_urls, 1), 0) || ' listing|' || coalesce(array_length(article_url_patterns, 1), 0) || ' patterns' FROM feeds WHERE publisher_id = 1560 ORDER BY id;
